<?php
if(!defined('ABSPATH'))exit;
function legacyx_staff_command_menu(){add_menu_page('Legacy X Firm OS','Firm OS','legacyx_access_firm_os','legacyx-firm-os','legacyx_render_staff_command','dashicons-chart-area',2);}add_action('admin_menu','legacyx_staff_command_menu');
function legacyx_staff_count($type,$statuses=array('publish','private','draft','pending')){$q=wp_count_posts($type);$c=0;foreach((array)$statuses as $s)if($q&&isset($q->$s))$c+=(int)$q->$s;return $c;}
function legacyx_staff_meta_count($type,$key,$values){$q=new WP_Query(array('post_type'=>$type,'post_status'=>'any','posts_per_page'=>1,'fields'=>'ids','meta_query'=>array(array('key'=>$key,'value'=>(array)$values,'compare'=>'IN'))));return (int)$q->found_posts;}
function legacyx_staff_client_label($id){$p=get_post($id);if(!$p)return 'Unassigned';$cid=get_post_meta($id,'_legacyx_client_id',true);return trim($p->post_title.($cid?' · '.$cid:''));}
function legacyx_staff_due_items(){return get_posts(array('post_type'=>array('legacyx_application','legacyx_work_item','legacyx_invoice'),'post_status'=>'any','numberposts'=>8,'meta_query'=>array('relation'=>'OR',array('key'=>'_legacyx_due_date','value'=>'','compare'=>'!='),array('key'=>'_legacyx_deadline','value'=>'','compare'=>'!=')),'orderby'=>'modified','order'=>'DESC'));}
function legacyx_render_staff_command(){if(!current_user_can('legacyx_access_firm_os'))return;$clients=legacyx_staff_count('legacyx_client');$assessments=legacyx_staff_count('legacyx_assessment');$apps=legacyx_staff_count('legacyx_application');$active_apps=legacyx_staff_meta_count('legacyx_application','_legacyx_status',array('Draft','Preparing','Ready','Submitted','Under Review','Additional Information Requested'));$work=legacyx_staff_count('legacyx_work_item');$open_work=legacyx_staff_meta_count('legacyx_work_item','_legacyx_work_status',array('Open','In Progress','Waiting on Client','Submitted','Under Review'));$invoices=legacyx_staff_count('legacyx_invoice');$open_invoices=legacyx_staff_meta_count('legacyx_invoice','_legacyx_status',array('Open','Partially Paid','Past Due'));$all_clients=get_posts(array('post_type'=>'legacyx_client','post_status'=>'any','numberposts'=>50,'orderby'=>'modified','order'=>'DESC'));$balance=0;foreach($all_clients as $c){$b=legacyx_billing_counts($c->ID);$balance+=(float)$b['balance'];}$recent=get_posts(array('post_type'=>array('legacyx_client','legacyx_application','legacyx_work_item','legacyx_invoice','legacyx_assessment'),'post_status'=>'any','numberposts'=>8,'orderby'=>'modified','order'=>'DESC'));$attention=get_posts(array('post_type'=>'legacyx_application','post_status'=>'any','numberposts'=>6,'meta_query'=>array(array('key'=>'_legacyx_status','value'=>array('Additional Information Requested','Under Review'),'compare'=>'IN')),'orderby'=>'modified','order'=>'DESC'));$due=legacyx_staff_due_items();?>
<div class="wrap legacyx-staff-os"><div class="legacyx-staff-hero"><div><span>LEGACY X FIRM OS · STAFF</span><h1>Executive Command Center</h1><p>One operational view across client relationships, assessments, applications, workflow, credit, business readiness and billing.</p></div><a href="<?php echo esc_url(home_url('/client-portal/'));?>" target="_blank" rel="noopener">Open Client Portal ↗</a></div>
<div class="legacyx-staff-metrics"><div><span>Clients</span><strong><?php echo esc_html($clients);?></strong><small>Universal profiles</small></div><div><span>Assessments</span><strong><?php echo esc_html($assessments);?></strong><small>Executive intake</small></div><div><span>Active Applications</span><strong><?php echo esc_html($active_apps);?></strong><small><?php echo esc_html($apps);?> total</small></div><div><span>Open Workflow</span><strong><?php echo esc_html($open_work);?></strong><small><?php echo esc_html($work);?> total items</small></div><div><span>Open Billing</span><strong><?php echo esc_html($open_invoices);?></strong><small><?php echo esc_html($invoices);?> billing records</small></div><div><span>Outstanding</span><strong><?php echo esc_html(legacyx_money($balance));?></strong><small>Across client profiles</small></div></div>
<div class="legacyx-staff-grid"><section><div class="legacyx-staff-section-head"><span>OPERATIONS</span><h2>Firm Modules</h2></div><div class="legacyx-staff-modules"><?php $mods=array(array('Clients','Universal client profiles','edit.php?post_type=legacyx_client','Manage Clients'),array('Assessments','Executive intake pipeline','edit.php?post_type=legacyx_assessment','Review Assessments'),array('Applications','Funding, grants and service applications','edit.php?post_type=legacyx_application','Manage Applications'),array('Documents & Tasks','Client workflow and document requests','edit.php?post_type=legacyx_work_item','Manage Workflow'),array('Billing & Payments','Invoices, retainers and payment records','edit.php?post_type=legacyx_invoice','Manage Billing'));foreach($mods as $m):?><article><span><?php echo esc_html($m[0]);?></span><h3><?php echo esc_html($m[1]);?></h3><a href="<?php echo esc_url(admin_url($m[2]));?>"><?php echo esc_html($m[3]);?> →</a></article><?php endforeach;?></div></section><aside><div class="legacyx-staff-section-head"><span>QUICK ACTIONS</span><h2>Create</h2></div><a class="legacyx-staff-action" href="<?php echo esc_url(admin_url('post-new.php?post_type=legacyx_client'));?>">+ New Client</a><a class="legacyx-staff-action" href="<?php echo esc_url(admin_url('post-new.php?post_type=legacyx_application'));?>">+ New Application</a><a class="legacyx-staff-action" href="<?php echo esc_url(admin_url('post-new.php?post_type=legacyx_work_item'));?>">+ New Task / Document</a><a class="legacyx-staff-action" href="<?php echo esc_url(admin_url('post-new.php?post_type=legacyx_invoice'));?>">+ New Invoice</a></aside></div>
<div class="legacyx-staff-two"><section><div class="legacyx-staff-section-head"><span>ATTENTION</span><h2>Needs Review</h2></div><?php if(!$attention):?><p class="legacyx-empty">No applications currently require special review.</p><?php else:foreach($attention as $r):?><a class="legacyx-alert-row" href="<?php echo esc_url(get_edit_post_link($r->ID));?>"><div><strong><?php echo esc_html(get_the_title($r));?></strong><small><?php echo esc_html(legacyx_staff_client_label((int)get_post_meta($r->ID,'_legacyx_client_id',true)));?></small></div><span><?php echo esc_html(get_post_meta($r->ID,'_legacyx_status',true));?> →</span></a><?php endforeach;endif;?></section><section><div class="legacyx-staff-section-head"><span>DEADLINES</span><h2>Upcoming / Dated Items</h2></div><?php if(!$due):?><p class="legacyx-empty">No dated workflow, application or billing items yet.</p><?php else:foreach($due as $r):$date=get_post_meta($r->ID,'_legacyx_due_date',true)?:get_post_meta($r->ID,'_legacyx_deadline',true);?><a class="legacyx-alert-row" href="<?php echo esc_url(get_edit_post_link($r->ID));?>"><div><strong><?php echo esc_html(get_the_title($r));?></strong><small><?php echo esc_html(get_post_type_object($r->post_type)->labels->singular_name);?></small></div><span><?php echo esc_html($date?:'Review');?> →</span></a><?php endforeach;endif;?></section></div>
<section class="legacyx-staff-recent legacyx-client-directory"><div class="legacyx-staff-section-head"><span>CLIENT DIRECTORY</span><h2>Client Relationships</h2></div><div class="legacyx-client-search"><input type="search" id="legacyx-client-search" placeholder="Search client, business, email or Client ID…"></div><table id="legacyx-client-table"><thead><tr><th>Client</th><th>Client ID</th><th>Business</th><th>Status</th><th>Capital Goal</th><th></th></tr></thead><tbody><?php if(!$all_clients):?><tr><td colspan="6">No client profiles yet.</td></tr><?php else:foreach($all_clients as $c):$cid=get_post_meta($c->ID,'_legacyx_client_id',true);$business=get_post_meta($c->ID,'_legacyx_business_name',true);$status=get_post_meta($c->ID,'_legacyx_status',true);$goal=get_post_meta($c->ID,'_legacyx_capital_goal',true);$email=get_post_meta($c->ID,'_legacyx_email',true);$view=add_query_arg(array('page'=>'legacyx-client-360','client_id'=>$c->ID),admin_url('admin.php'));?><tr data-search="<?php echo esc_attr(strtolower($c->post_title.' '.$cid.' '.$business.' '.$email));?>"><td><strong><?php echo esc_html($c->post_title);?></strong><?php if($email):?><small><?php echo esc_html($email);?></small><?php endif;?></td><td><?php echo esc_html($cid?:'—');?></td><td><?php echo esc_html($business?:'—');?></td><td><?php echo esc_html($status?:'—');?></td><td><?php echo esc_html($goal?:'—');?></td><td><a href="<?php echo esc_url($view);?>">Open 360 →</a></td></tr><?php endforeach;endif;?></tbody></table></section>
<section class="legacyx-staff-recent"><div class="legacyx-staff-section-head"><span>RECENT ACTIVITY</span><h2>Latest Records</h2></div><table><thead><tr><th>Record</th><th>Module</th><th>Updated</th><th></th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="4">No records yet.</td></tr><?php else:foreach($recent as $r):$obj=get_post_type_object($r->post_type);?><tr><td><strong><?php echo esc_html(get_the_title($r)?:'(Untitled)');?></strong></td><td><?php echo esc_html($obj?$obj->labels->singular_name:$r->post_type);?></td><td><?php echo esc_html(get_the_modified_date('M j, Y g:i a',$r));?></td><td><a href="<?php echo esc_url(get_edit_post_link($r->ID));?>">Open →</a></td></tr><?php endforeach;endif;?></tbody></table></section></div><script>document.addEventListener('DOMContentLoaded',function(){var q=document.getElementById('legacyx-client-search'),t=document.getElementById('legacyx-client-table');if(!q||!t)return;q.addEventListener('input',function(){var v=this.value.toLowerCase().trim();t.querySelectorAll('tbody tr[data-search]').forEach(function(r){r.style.display=!v||r.dataset.search.indexOf(v)!==-1?'':'none';});});});</script><?php }
function legacyx_staff_command_styles($hook){if($hook!=='toplevel_page_legacyx-firm-os')return;wp_register_style('legacyx-staff-os',false);wp_enqueue_style('legacyx-staff-os');$css='.legacyx-staff-os{max-width:1440px;margin:24px 24px 60px 4px;color:#171512}.legacyx-staff-hero{background:#171512;color:#fff;padding:34px 38px;display:flex;justify-content:space-between;align-items:flex-end;border-radius:4px}.legacyx-staff-hero span,.legacyx-staff-section-head span{font-size:11px;font-weight:800;letter-spacing:.16em;color:#f05a16}.legacyx-staff-hero h1{font-family:Georgia,serif;font-size:38px;margin:8px 0}.legacyx-staff-hero p{max-width:760px;color:#c9c3ba;font-size:15px}.legacyx-staff-hero>a{background:#f05a16;color:#fff;text-decoration:none;padding:13px 18px;font-weight:700}.legacyx-staff-metrics{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid #ded8ce;background:#fff;margin-top:18px}.legacyx-staff-metrics>div{padding:22px;border-right:1px solid #ded8ce}.legacyx-staff-metrics>div:last-child{border:0}.legacyx-staff-metrics span,.legacyx-staff-metrics small,.legacyx-client-directory td small{display:block;color:#746e65}.legacyx-staff-metrics strong{display:block;font-family:Georgia,serif;font-size:28px;margin:7px 0}.legacyx-staff-grid{display:grid;grid-template-columns:3fr 1fr;gap:18px;margin-top:18px}.legacyx-staff-grid>section,.legacyx-staff-grid>aside,.legacyx-staff-recent,.legacyx-staff-two>section{background:#fff;border:1px solid #ded8ce;padding:28px}.legacyx-staff-section-head h2{font-family:Georgia,serif;font-size:27px;margin:5px 0 20px}.legacyx-staff-modules{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.legacyx-staff-modules article{border:1px solid #e4dfd6;padding:20px}.legacyx-staff-modules article>span{font-size:11px;font-weight:800;letter-spacing:.12em;color:#f05a16}.legacyx-staff-modules h3{font-size:15px;margin:8px 0 18px}.legacyx-staff-modules a,.legacyx-staff-recent a{color:#171512;font-weight:700;text-decoration:none}.legacyx-staff-action{display:block;background:#f7f4ed;color:#171512;text-decoration:none;font-weight:700;padding:14px;margin-bottom:10px;border-left:3px solid #f05a16}.legacyx-staff-two{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.legacyx-alert-row{display:flex;justify-content:space-between;gap:15px;align-items:center;padding:14px 0;border-bottom:1px solid #e4dfd6;text-decoration:none;color:#171512}.legacyx-alert-row small{display:block;color:#746e65;margin-top:4px}.legacyx-alert-row>span{font-weight:700;color:#f05a16;text-align:right}.legacyx-empty{color:#746e65}.legacyx-staff-recent{margin-top:18px}.legacyx-staff-recent table{width:100%;border-collapse:collapse}.legacyx-staff-recent th,.legacyx-staff-recent td{text-align:left;padding:13px;border-bottom:1px solid #e4dfd6}.legacyx-client-search{margin:-5px 0 18px}.legacyx-client-search input{width:100%;max-width:520px;padding:10px 14px;border:1px solid #cfc8bd;border-radius:2px}.legacyx-client-directory td small{margin-top:4px}@media(max-width:1100px){.legacyx-staff-metrics{grid-template-columns:repeat(3,1fr)}.legacyx-staff-grid,.legacyx-staff-two{grid-template-columns:1fr}}@media(max-width:700px){.legacyx-staff-hero{display:block}.legacyx-staff-hero>a{display:inline-block;margin-top:15px}.legacyx-staff-metrics,.legacyx-staff-modules{grid-template-columns:1fr}.legacyx-staff-metrics>div{border-right:0;border-bottom:1px solid #ded8ce}.legacyx-staff-recent{overflow:auto}}';wp_add_inline_style('legacyx-staff-os',$css);}add_action('admin_enqueue_scripts','legacyx_staff_command_styles');
